  ('1a9c131f-3e6b-5182-868c-ad907a16b5b1', 'Jonas Winter-test', '19b99cd7-c067-5ae8-b5ba-88b4dab9678f', 'male', 1998, 'Kelowna', 'BC', 'CA', 2022, array['sword_shield', '5v5']::text[], 'Sword and shield: uses the rim to take space', 'Jonas Winter fights for Frostborn Raiders-test, the Kelowna club in Kelowna. Joined in 2022. Enters Sword & Shield, 5v5. Has attended 4 NACL-test events (2024 to 2026) and fought 13 matches for a 3-10 record. A losing record so far. Has reached the podium 2 times.', array['Silver, Male 5v5, Pacific Steel Championship-test (2026)', 'Silver, Male 5v5, Battle of the Badlands-test (2024)', 'Career record 3-10 over 13 matches at 4 events', 'Joined Frostborn Raiders-test in 2022']::text[]),
  ('54a3231b-0712-5fe9-8b22-4e8cca02a99c', 'Kristoff Ice-test', '19b99cd7-c067-5ae8-b5ba-88b4dab9678f', 'male', 1996, 'Kelowna', 'BC', 'CA', 2021, array['longsword', '3v3', '5v5']::text[], 'Longsword: pressure with the point, then close the line', 'Kristoff Ice fights for Frostborn Raiders-test, the Kelowna club in Kelowna. Joined in 2021. Enters Longsword, 3v3, 5v5. Has attended 4 NACL-test events (2023 to 2026) and fought 27 matches for a 10-17 record. A losing record so far. Has reached the podium 2 times.', array['Silver, Male 5v5, Pacific Steel Championship-test (2026)', 'Bronze, Male Longsword, Pacific Steel Championship-test (2026)', 'Career record 10-17 over 27 matches at 4 events', 'Joined Frostborn Raiders-test in 2021']::text[]),
  ('98146ed7-d388-5e3c-822d-f8d5285044bf', 'Lars Frost-test', '19b99cd7-c067-5ae8-b5ba-88b4dab9678f', 'male', 1989, 'Vernon', 'BC', 'CA', 2019, array['polearm']::text[], 'Polearm: steady point work and good footwork', 'Lars Frost fights for Frostborn Raiders-test, the Kelowna club in Kelowna. A veteran who joined in 2019. Enters Polearm. Has attended 3 NACL-test events (2024 to 2026) and fought 9 matches for a 8-1 record. A winning record overall. A tournament winner (2 gold). Has reached the podium 3 times. Ranked 2 of 23 in Male Polearm on career points.', array['Gold, Male Polearm, Rocky Mountain Rumble-test (2026)', 'Gold, Male Polearm, Okanagan Armored Open-test (2024)', 'Bronze, Male Polearm, Pacific Steel Championship-test (2026)', 'Career record 8-1 over 9 matches at 3 events', 'Career rank 2 of 23 in Male Polearm', 'Joined Frostborn Raiders-test in 2019']::text[]),
  ('f5cc5373-d952-5604-adde-f304f3f6c86e', 'Mikkel Winter-test', '19b99cd7-c067-5ae8-b5ba-88b4dab9678f', 'male', 2000, 'Kelowna', 'BC', 'CA', 2023, array['sword_shield']::text[], 'Sword and shield: uses the rim to take space', 'Mikkel Winter fights for Frostborn Raiders-test, the Kelowna club in Kelowna. Joined in 2023. Enters Sword & Shield. Has attended 5 NACL-test events (2023 to 2026) and fought 8 matches for a 1-7 record. A losing record so far. Has yet to reach a podium.', array['Career record 1-7 over 8 matches at 5 events', 'Joined Frostborn Raiders-test in 2023']::text[]),
  ('31375f7d-13ba-5a5f-95ec-75173fd0c9a1', 'Niklas Ice-test', '19b99cd7-c067-5ae8-b5ba-88b4dab9678f', 'male', 2002, 'Kelowna', 'BC', 'CA', 2024, array['longsword', '3v3']::text[], 'Longsword: patient, technical and hard to bait', 'Niklas Ice fights for Frostborn Raiders-test, the Kelowna club in Kelowna. A newer competitor, joined in 2024. Enters Longsword, 3v3. Has attended 5 NACL-test events (2024 to 2026) and fought 23 matches for a 8-15 record. A losing record so far. Has yet to reach a podium.', array['Career record 8-15 over 23 matches at 5 events', 'Joined Frostborn Raiders-test in 2024']::text[]),
  ('f263eeb9-8098-5d5a-8b30-36c01db0900d', 'Saga Ice-test', '19b99cd7-c067-5ae8-b5ba-88b4dab9678f', 'female', 1995, 'Kelowna', 'BC', 'CA', 2021, array['longsword', '5v5']::text[], 'Longsword: patient, technical and hard to bait', 'Saga Ice fights for Frostborn Raiders-test, the Kelowna club in Kelowna. Joined in 2021. Enters Longsword, 5v5. Has attended 2 NACL-test events (2024) and fought 3 matches for a 0-3 record. Has reached the podium once.', array['Silver, Female 5v5, Edmonton Winter Melee-test (2024)', 'Career record 0-3 over 3 matches at 2 events', 'Joined Frostborn Raiders-test in 2021']::text[]),
  ('4ab1a10e-bf97-5cb4-882d-57cf6f0f9466', 'Thyra Frost-test', '19b99cd7-c067-5ae8-b5ba-88b4dab9678f', 'female', 1992, 'Vernon', 'BC', 'CA', 2020, array['polearm']::text[], 'Polearm: steady point work and good footwork', 'Thyra Frost fights for Frostborn Raiders-test, the Kelowna club in Kelowna. A veteran who joined in 2020. Enters Polearm. Has attended 2 NACL-test events (2023 to 2026) and fought 2 matches for a 0-2 record. Has yet to reach a podium.', array['Career record 0-2 over 2 matches at 2 events', 'Joined Frostborn Raiders-test in 2020']::text[]),
  ('5777bdcc-18bc-518f-a88f-103441365171', 'Ursa Winter-test', '19b99cd7-c067-5ae8-b5ba-88b4dab9678f', 'female', 1999, 'Kelowna', 'BC', 'CA', 2022, array['sword_shield']::text[], 'Sword and shield: defensive base with sudden speed', 'Ursa Winter fights for Frostborn Raiders-test, the Kelowna club in Kelowna. Joined in 2022. Enters Sword & Shield. Has attended 5 NACL-test events (2023 to 2026) and fought 11 matches for a 1-10 record. A losing record so far. Has yet to reach a podium.', array['Career record 1-10 over 11 matches at 5 events', 'Joined Frostborn Raiders-test in 2022']::text[]),
  ('9b130d30-471b-5ccf-9192-7e0c04af836e', 'Valka Ice-test', '19b99cd7-c067-5ae8-b5ba-88b4dab9678f', 'female', 1997, 'Kelowna', 'BC', 'CA', 2021, array['longsword', '3v3', '5v5']::text[], 'Longsword: measured distance and clean second intentions', 'Valka Ice fights for Frostborn Raiders-test, the Kelowna club in Kelowna. Joined in 2021. Enters Longsword, 3v3, 5v5. Has attended 3 NACL-test events (2024 to 2026) and fought 11 matches for a 7-4 record. A winning record overall. A tournament winner (2 gold). Has reached the podium 3 times.', array['Gold, Female Longsword, Pacific Steel Championship-test (2026)', 'Gold, Female 3v3, Edmonton Winter Melee-test (2024)', 'Silver, Female 5v5, Edmonton Winter Melee-test (2024)', 'Career record 7-4 over 11 matches at 3 events', 'Joined Frostborn Raiders-test in 2021']::text[]),
  ('6bc467da-ab8c-5ac2-afc2-ad667738310c', 'Willow Frost-test', '19b99cd7-c067-5ae8-b5ba-88b4dab9678f', 'female', 2001, 'Kelowna', 'BC', 'CA', 2023, array['polearm', '5v5']::text[], 'Polearm: steady point work and good footwork', 'Willow Frost fights for Frostborn Raiders-test, the Kelowna club in Kelowna. Joined in 2023. Enters Polearm, 5v5. Has attended 2 NACL-test events (2024 to 2026) and fought 2 matches for a 0-2 record. Has reached the podium once.', array['Silver, Female 5v5, Edmonton Winter Melee-test (2024)', 'Career record 0-2 over 2 matches at 2 events', 'Joined Frostborn Raiders-test in 2023']::text[])
